mapper.select:
/* PdaLocationPaloMapper.selectPkgNoInfo : 로케이션적치 - 박스번호조회 */
SELECT TOP 1 '반입예정' AS dGbn , P.BL_NO , P.OD_JOB_NO , P.CARGO_REFERENCE_NO , PP.PACKING_NO , P.EX_CT AS CT , P.EX_WT AS WT , P.IN_PLAN_NO , PP.LOCATION_PLACE , 0 AS IN_NO , H.CARRYOUT_STOP_YN , 'N' AS INSPECTION , 'N' AS INSPECTION_FINISH_YN , '' AS HOLD_HISTORY , '' AS APPROVAL_DATE , 0 AS STORAGE_DAYS , 1 AS SORT_SEQ FROM TB_BMS_IN_PLAN_PKG PP WITH (NOLOCK) INNER JOIN TB_BMS_IN_PLAN P WITH (NOLOCK) ON PP.IN_PLAN_NO = P.IN_PLAN_NO LEFT JOIN (SELECT MAX(CARRYOUT_STOP_YN) AS CARRYOUT_STOP_YN, OD_JOB_NO FROM TB_ECM_OD_HOLD WITH (NOLOCK) WHERE HOLD_RELEASE_YN = 'N' GROUP BY OD_JOB_NO) H ON P.OD_JOB_NO = H.OD_JOB_NO WHERE PP.PACKING_NO = #{srchNo} AND PP.DELETE_YN = 'N' AND PP.OUT_CT = 0
AND PP.IN_PLAN_NO = #{srchInPlanNo}
AND P.BL_NO = #{srchBlNo}
UNION ALL SELECT TOP 1 '반입' AS dGbn , I.BL_NO , I.OD_JOB_NO , I.CARGO_REFERENCE_NO , PP.PACKING_NO , I.CT , I.WT , I.IN_PLAN_NO , PP.LOCATION_PLACE , I.IN_NO , H.CARRYOUT_STOP_YN , CASE WHEN I.SE_INSPECTION_CODE <> '' OR I.INSPECTION_TYPE <> '' OR I.INSPECTION_TYPE_A <> '' OR I.INSPECTION_TYPE_B <> '' OR I.XRAY_INSPECTION_CODE <> '' OR I.PALN5EM_INSPECTION_CODE <> '' THEN 'Y' ELSE 'N' END AS INSPECTION , ISNULL(IR.M_INSPECTION_FINISH_YN, 'N') AS INSPECTION_FINISH_YN , ISNULL(H.HOLD_HISTORY, 'N') AS HOLD_HISTORY , ISNULL(OP.APPROVAL_DATE, '') AS APPROVAL_DATE , CASE WHEN DATEDIFF(DAY, CONVERT(DATE, NULLIF(LTRIM(RTRIM(I.CARRYIN_DATE)), ''), 23), GETDATE()) + 1 < 1 THEN 1 ELSE DATEDIFF(DAY, CONVERT(DATE, NULLIF(LTRIM(RTRIM(I.CARRYIN_DATE)), ''), 23), GETDATE()) + 1 END AS STORAGE_DAYS , 2 AS SORT_SEQ FROM TB_BMS_IN_PLAN_PKG PP WITH (NOLOCK) INNER JOIN TB_BMS_IN I WITH (NOLOCK) ON PP.IN_PLAN_NO = I.IN_PLAN_NO LEFT JOIN TB_BMS_OUT_PLAN OP WITH (NOLOCK) ON I.IN_NO = OP.IN_NO LEFT JOIN (SELECT 'Y' AS HOLD_HISTORY, OD_JOB_NO, MAX(CARRYOUT_STOP_YN) AS CARRYOUT_STOP_YN FROM TB_ECM_OD_HOLD WITH (NOLOCK) GROUP BY OD_JOB_NO) H ON I.OD_JOB_NO = H.OD_JOB_NO LEFT JOIN (SELECT IN_NO, MIN(INSPECTION_FINISH_YN) M_INSPECTION_FINISH_YN FROM TB_BMS_INSPECT_RESULT WITH (NOLOCK) GROUP BY IN_NO) IR ON I.IN_NO = IR.IN_NO WHERE PP.PACKING_NO = #{srchNo} AND PP.DELETE_YN = 'N' AND PP.OUT_CT = 0
AND PP.IN_PLAN_NO = #{srchInPlanNo}
AND I.BL_NO = #{srchBlNo}

/* PdaLocationPaloMapper.selectPkgNoInfoNew : new 로케이션적치 - 박스번호조회 */ SELECT TOP 1 CASE WHEN ISNULL(I.IN_NO, 0) <> 0 THEN '반입' ELSE '반입예정' END AS dGbn , P.BL_NO , P.OD_JOB_NO , P.CARGO_REFERENCE_NO , PP.PACKING_NO , COALESCE(I.CT, P.EX_CT) AS CT , COALESCE(I.WT, P.EX_WT) AS WT , P.IN_PLAN_NO , PP.LOCATION_PLACE , PP.ORIG_LOCATION_PLACE , I.IN_NO AS IN_NO , H.CARRYOUT_STOP_YN , ISNULL(H.HOLD_HISTORY, 'N') AS HOLD_HISTORY , ISNULL(OP.APPROVAL_DATE, '') AS APPROVAL_DATE , CASE WHEN I.IN_NO IS NULL THEN 0 WHEN DATEDIFF(DAY, CONVERT(DATE, NULLIF(LTRIM(RTRIM(I.CARRYIN_DATE)), ''), 23), GETDATE()) + 1 < 1 THEN 1 ELSE DATEDIFF(DAY, CONVERT(DATE, NULLIF(LTRIM(RTRIM(I.CARRYIN_DATE)), ''), 23), GETDATE()) + 1 END AS STORAGE_DAYS , P.SE_INSPECTION_CODE , P.PALN5EM_INSPECTION_CODE , XR.XRAY_INSPECTION_CODE AS XRAY_INSPECTION_CODE , P.INSPECTION_TYPE , P.INSPECTION_TYPE_A , P.INSPECTION_TYPE_B , P.BIG_SIZE_YN , P.INSPECTION_CUSTOMS_YN , P.INTELLECTUAL_PROP_YN , P.CRIME_SELECTION_YN , PP.DELETE_YN
, ( SELECT ALL_INSPECTION_FINISH_YN FROM TB_BMS_IN WITH (NOLOCK) WHERE IN_PLAN_NO = #{srchInPlanNo} ) AS ALL_INSPECTION_FINISH_YN
, 'N' AS ALL_INSPECTION_FINISH_YN
FROM TB_BMS_IN_PLAN_PKG PP WITH (NOLOCK) INNER JOIN TB_BMS_IN_PLAN P WITH (NOLOCK) ON PP.IN_PLAN_NO = P.IN_PLAN_NO LEFT JOIN (SELECT MAX(CARRYOUT_STOP_YN) AS CARRYOUT_STOP_YN, OD_JOB_NO, 'Y' AS HOLD_HISTORY FROM TB_ECM_OD_HOLD WITH (NOLOCK) WHERE HOLD_RELEASE_YN = 'N' GROUP BY OD_JOB_NO) H ON P.OD_JOB_NO = H.OD_JOB_NO LEFT JOIN TB_BMS_XRAY_RESULT XR ON XR.IN_PLAN_NO = PP.IN_PLAN_NO
LEFT JOIN (SELECT TOP 1 IN_NO , IN_PLAN_NO , CARRYIN_DATE , ORIG_IN_PLAN_NO , CT , WT FROM TB_BMS_IN WITH (NOLOCK) WHERE IN_PLAN_NO = #{srchInPlanNo} OR ORIG_IN_PLAN_NO = #{srchInPlanNo} ORDER BY CAST(CARRYIN_DATE + ' ' + CARRYIN_TIME AS DATETIME) DESC ) I
LEFT JOIN (SELECT NULL AS IN_NO , NULL AS IN_PLAN_NO , NULL AS CARRYIN_DATE , NULL AS ORIG_IN_PLAN_NO , NULL AS CT , NULL AS WT ) I
ON I.IN_PLAN_NO = PP.IN_PLAN_NO OR I.ORIG_IN_PLAN_NO = PP.IN_PLAN_NO LEFT JOIN TB_BMS_OUT_PLAN OP WITH (NOLOCK) ON I.IN_NO = OP.IN_NO WHERE PP.PACKING_NO = #{srchNo}
AND PP.IN_PLAN_NO = #{srchInPlanNo}
AND P.BL_NO = #{srchBlNo}

/* PdaLocationPaloMapper.selectPkgNoByPlanNoAndBlNo : 로케이션적치 - 박스조회 */ SELECT P.BL_NO , P.OD_JOB_NO , P.CARGO_REFERENCE_NO , PP.PACKING_NO , P.EX_CT AS CT , P.EX_WT AS WT , P.IN_PLAN_NO , PP.LOCATION_PLACE , ISNULL(I.IN_NO, 0) AS IN_NO , ISNULL(I.ALL_INSPECTION_FINISH_YN, '') AS ALL_INSPECTION_FINISH_YN , H.CARRYOUT_STOP_YN , CASE WHEN I.SE_INSPECTION_CODE <> '' OR I.INSPECTION_TYPE <> '' OR I.INSPECTION_TYPE_A <> '' OR I.INSPECTION_TYPE_B <> '' OR I.XRAY_INSPECTION_CODE <> '' OR I.PALN5EM_INSPECTION_CODE <> '' THEN 'Y' ELSE 'N' END AS INSPECTION , ISNULL(IR.M_INSPECTION_FINISH_YN, 'N') AS INSPECTION_FINISH_YN , ISNULL(H.HOLD_HISTORY, 'N') AS HOLD_HISTORY , ISNULL(OP.APPROVAL_DATE, '') AS APPROVAL_DATE , CASE WHEN DATEDIFF(DAY, CONVERT(DATE, NULLIF(LTRIM(RTRIM(I.CARRYIN_DATE)), ''), 23), GETDATE()) + 1 < 1 THEN 1 ELSE DATEDIFF(DAY, CONVERT(DATE, NULLIF(LTRIM(RTRIM(I.CARRYIN_DATE)), ''), 23), GETDATE()) + 1 END AS STORAGE_DAYS FROM TB_BMS_IN_PLAN_PKG PP WITH (NOLOCK) INNER JOIN TB_BMS_IN_PLAN P WITH (NOLOCK) ON PP.IN_PLAN_NO = P.IN_PLAN_NO LEFT JOIN TB_BMS_IN I WITH (NOLOCK) ON PP.IN_PLAN_NO = I.IN_PLAN_NO LEFT JOIN TB_BMS_OUT_PLAN OP WITH (NOLOCK) ON I.IN_NO = OP.IN_NO LEFT JOIN (SELECT 'Y' AS HOLD_HISTORY, OD_JOB_NO, MAX(CARRYOUT_STOP_YN) AS CARRYOUT_STOP_YN FROM TB_ECM_OD_HOLD WITH (NOLOCK) GROUP BY OD_JOB_NO) H ON I.OD_JOB_NO = H.OD_JOB_NO LEFT JOIN (SELECT IN_NO, MIN(INSPECTION_FINISH_YN) M_INSPECTION_FINISH_YN FROM TB_BMS_INSPECT_RESULT WITH (NOLOCK) GROUP BY IN_NO) IR ON I.IN_NO = IR.IN_NO WHERE PP.DELETE_YN = 'N' AND PP.OUT_CT = 0
AND PP.IN_PLAN_NO = #{srchInPlanNo}
AND P.BL_NO = #{srchBlNo}
AND PP.LOCATION_STATUS = #{srchLocationStatus}
AND PP.LOCATION_STATUS <> #{srchNotLocationStatus}

mapper.update:
		/* PdaLocationPaloMapper.updateBmsInAndInPlanPkgLocationInfo : 로케이션적치 - 반입예정 PKG 업데이트 */
		UPDATE PP
		   SET PP.LOCATION_PLACE = #{locationPlace}
		   	 , PP.ORIG_LOCATION_PLACE = 
		   	 				 CASE 
                                WHEN PP.ORIG_LOCATION_PLACE = '' THEN #{locationPlace} 
                                ELSE PP.ORIG_LOCATION_PLACE 
                             END
		   	 , PP.LOCATION_STATUS = 'L'
		   	 , PP.UPDATE_USER_ID = #{updateUserId}
		   	 , PP.UPDATE_DATE_TIME = GETDATE()
		  FROM TB_BMS_IN_PLAN_PKG PP
		  JOIN TB_BMS_IN_PLAN P WITH (NOLOCK)
		    ON PP.IN_PLAN_NO = P.IN_PLAN_NO
		 WHERE PP.PACKING_NO = #{packingNo}
		   AND PP.IN_PLAN_NO = #{inPlanNo}

		   AND P.BL_NO = #{srchBlNo}

		;

/* PdaLocationPaloMapper.updateBmsInAndInPlanPkgLocationInfo : 로케이션적치 - 반입예정 PKG 업데이트 */
IF(#{srchOrigLocation} IS NOT NULL and #{srchOrigLocation} <> '')
	BEGIN
		IF (#{applyAllLoactionYn} = 'Y' and #{inPlanNo} IS NOT NULL and #{inPlanNo} <> '' and #{inPlanNo} > 0)
			BEGIN
				UPDATE TB_BMS_IN_PLAN_PKG
					SET 
						ORIG_LOCATION_PLACE = #{srchOrigLocation}
					   	, LOCATION_PLACE = CASE 
					   							WHEN PACKING_NO = #{packingNo} THEN #{locationPlace}
					   							ELSE LOCATION_PLACE
					   					    END
					   	, LOCATION_STATUS = CASE 
					   							WHEN PACKING_NO = #{packingNo} THEN 'L'
					   							ELSE LOCATION_STATUS
					   					    END
						, UPDATE_USER_ID = #{updateUserId}
			   	 		, UPDATE_DATE_TIME = GETDATE()
				WHERE IN_PLAN_NO = #{inPlanNo}
					AND DELETE_YN = 'N'
			END
		ELSE
			BEGIN
				UPDATE TB_BMS_IN_PLAN_PKG
					SET 
						LOCATION_PLACE = #{locationPlace}
					   	, ORIG_LOCATION_PLACE = #{srchOrigLocation}
					   	, LOCATION_STATUS = 'L'
						, UPDATE_USER_ID = #{updateUserId}
			   	 		, UPDATE_DATE_TIME = GETDATE()
				WHERE PACKING_NO = #{packingNo}

					AND IN_PLAN_NO = #{inPlanNo}


					AND BL_NO = #{srchBlNo}

					AND DELETE_YN = 'N'
			END
	END
ELSE
	BEGIN
		UPDATE TB_BMS_IN_PLAN_PKG
		   SET LOCATION_PLACE = #{locationPlace}
		   	 , ORIG_LOCATION_PLACE = CASE 
			   							WHEN ORIG_LOCATION_PLACE = '' THEN #{locationPlace}
			   							ELSE ORIG_LOCATION_PLACE
			   					    END
		   	 , LOCATION_STATUS = 'L'
		   	 , UPDATE_USER_ID = #{updateUserId}
		   	 , UPDATE_DATE_TIME = GETDATE()
		 WHERE IN_PLAN_NO = #{inPlanNo}

		 	AND PACKING_NO = #{packingNo}


		    AND BL_NO = #{srchBlNo}

	END
;

	/* PdaLocationPaloMapper.updateBmsInLocationInfo : 로케이션적치 - 반입 로케이션정보 업데이트 */
     UPDATE TB_BMS_IN
   	   SET LOCATION_PLACE = #{locationPlace}
   	 	 , UPDATE_USER_ID = #{updateUserId}
   	 	 , UPDATE_DATE_TIME = GETDATE()
 	 WHERE CARGO_REFERENCE_NO = #{cargoReferenceNo}

	/* PdaLocationPaloMapper.updateLocationFromInPlanPkg : 로케이션적치 - 반입예정 PKG, 반입 로케이션정보 업데이트 */
	UPDATE PP
	   SET PP.LOCATION_PLACE = #{locationPlace}
	   	 , PP.ORIG_LOCATION_PLACE = CASE 
	   							WHEN PP.ORIG_LOCATION_PLACE = '' THEN #{locationPlace}
	   							ELSE PP.ORIG_LOCATION_PLACE
	   					    END
	   	 , PP.LOCATION_STATUS = 'L'
	   	 , PP.UPDATE_USER_ID = #{updateUserId}
	   	 , PP.UPDATE_DATE_TIME = GETDATE()
	  FROM TB_BMS_IN_PLAN_PKG PP
	  JOIN TB_BMS_IN_PLAN P WITH (NOLOCK)
	    ON PP.IN_PLAN_NO = P.IN_PLAN_NO
	 WHERE PP.IN_PLAN_NO = #{inPlanNo}

	   AND P.BL_NO = #{srchBlNo}

	;

	UPDATE TB_BMS_IN
   	   SET LOCATION_PLACE = #{locationPlace}
   	 	 , UPDATE_USER_ID = #{updateUserId}
   	 	 , UPDATE_DATE_TIME = GETDATE()
 	 WHERE 
 	 	IN_NO = #{inNo}
 	 	OR ORIG_IN_PLAN_NO = #{inPlanNo};

/* PdaLocationPaloMapper.updateInPlanPkgLocationInfo : 로케이션정보 업데이트 */
UPDATE _pkg
   SET _pkg.LOCATION_STATUS = #{locationStatus}
   	 , _pkg.LOCATION_PLACE = ''
   	 , _pkg.UPDATE_USER_ID = #{updateUserId}
   	 , _pkg.UPDATE_DATE_TIME = GETDATE()
  FROM TB_BMS_IN_PLAN_PKG _pkg
  JOIN TB_BMS_IN_PLAN _inPlan WITH (NOLOCK)
    ON _pkg.IN_PLAN_NO = _inPlan.IN_PLAN_NO
 WHERE _pkg.PACKING_NO = #{packingNo}

   AND _pkg.IN_PLAN_NO = #{inPlanNo}


   AND _inPlan.BL_NO = #{blNo}

mapper.select:
/* PdaLocationPaloMapper.selectBmsInHoldInfo : 로케이션적치 - 홀드조회 */ SELECT PP.PACKING_NO , P.OD_JOB_NO , HOLD_CODE , ISNULL((SELECT NAME_DEFAULT FROM TB_SMS_CODE_DETAIL WHERE CODE = H.HOLD_CODE AND ENT_CODE = #{srchEntCode} AND GROUP_CODE='HOLD_CODE' AND USE_YN='Y'), '') AS HOLD_CODE_NAME , HOLD_DATE , HOLD_RELEASE_YN FROM TB_BMS_IN_PLAN_PKG PP WITH (NOLOCK) INNER JOIN TB_BMS_IN_PLAN P WITH (NOLOCK) ON PP.IN_PLAN_NO = P.IN_PLAN_NO LEFT JOIN TB_ECM_OD_HOLD H WITH (NOLOCK) ON P.OD_JOB_NO = H.OD_JOB_NO WHERE PP.PACKING_NO = #{srchNo}
AND PP.IN_PLAN_NO = #{srchInPlanNo}
AND P.BL_NO = #{srchBlNo}

/* PdaLocationPaloMapper.selectBmsInInspectionInfo : 로케이션적치 - 검사,검역조회 */ SELECT TOP 1 PP.PACKING_NO , P.BL_NO , CASE WHEN ISNULL(I.SE_INSPECTION_CODE, '') = '' THEN P.SE_INSPECTION_CODE ELSE I.SE_INSPECTION_CODE END AS SE_INSPECTION_CODE , CASE WHEN ISNULL(I.SE_INSPECTION_CODE, '') = '' THEN ISNULL((SELECT NAME_DEFAULT FROM TB_SMS_CODE_DETAIL WHERE CODE = P.SE_INSPECTION_CODE AND ENT_CODE = #{srchEntCode} AND GROUP_CODE='SE_INSPECTION_CODE' AND USE_YN='Y'), '') ELSE ISNULL((SELECT NAME_DEFAULT FROM TB_SMS_CODE_DETAIL WHERE CODE = I.SE_INSPECTION_CODE AND ENT_CODE = #{srchEntCode} AND GROUP_CODE='SE_INSPECTION_CODE' AND USE_YN='Y'), '') END AS SE_INSPECTION_CODE_NAME , I.XRAY_INSPECTION_CODE , ISNULL((SELECT NAME_DEFAULT FROM TB_SMS_CODE_DETAIL WHERE CODE = I.XRAY_INSPECTION_CODE AND ENT_CODE = #{srchEntCode} AND GROUP_CODE='SE_INSPECTION_CODE' AND USE_YN='Y' AND UPPER(CODE) NOT IN ('C')), '') AS XRAY_INSPECTION_CODE_NAME , CASE WHEN ISNULL(I.PALN5EM_INSPECTION_CODE, '') = '' THEN P.PALN5EM_INSPECTION_CODE ELSE I.PALN5EM_INSPECTION_CODE END AS PALN5EM_INSPECTION_CODE , CASE WHEN ISNULL(I.PALN5EM_INSPECTION_CODE, '') = '' THEN ISNULL((SELECT NAME_DEFAULT FROM TB_SMS_CODE_DETAIL WHERE CODE = P.PALN5EM_INSPECTION_CODE AND ENT_CODE = #{srchEntCode} AND GROUP_CODE='SE_INSPECTION_CODE' AND USE_YN='Y'), '') ELSE ISNULL((SELECT NAME_DEFAULT FROM TB_SMS_CODE_DETAIL WHERE CODE = I.PALN5EM_INSPECTION_CODE AND ENT_CODE = #{srchEntCode} AND GROUP_CODE='SE_INSPECTION_CODE' AND USE_YN='Y'), '') END AS PALN5EM_INSPECTION_CODE_NAME , CASE WHEN ISNULL(I.INSPECTION_TYPE, '') = '' THEN P.INSPECTION_TYPE ELSE I.INSPECTION_TYPE END AS INSPECTION_TYPE , CASE WHEN ISNULL(I.INSPECTION_TYPE, '') = '' THEN ISNULL((SELECT NAME_DEFAULT FROM TB_SMS_CODE_DETAIL WHERE CODE = P.INSPECTION_TYPE AND ENT_CODE = #{srchEntCode} AND GROUP_CODE='INSPECTION_TYPE' AND USE_YN='Y' AND ETC1='Y'), '') ELSE ISNULL((SELECT NAME_DEFAULT FROM TB_SMS_CODE_DETAIL WHERE CODE = I.INSPECTION_TYPE AND ENT_CODE = #{srchEntCode} AND GROUP_CODE='INSPECTION_TYPE' AND USE_YN='Y' AND ETC1='Y'), '') END AS INSPECTION_TYPE_NAME FROM TB_BMS_IN_PLAN_PKG PP WITH (NOLOCK) INNER JOIN TB_BMS_IN_PLAN P WITH (NOLOCK) ON PP.IN_PLAN_NO = P.IN_PLAN_NO LEFT JOIN TB_BMS_IN I WITH (NOLOCK) ON PP.IN_PLAN_NO = I.IN_PLAN_NO WHERE PP.PACKING_NO = #{srchNo}
AND PP.IN_PLAN_NO = #{srchInPlanNo}
AND P.BL_NO = #{srchBlNo}

/* PdaLocationPaloMapper.selectScanLogInfo : 로케이션 스캔로그 조회 */
SELECT SCAN_NO , BL_NO , SCAN_DATE , SCAN_RESULT , LOCATION_PLACE , ISNULL((SELECT TOP 1 NAME_DEFAULT FROM TB_SMS_CODE_DETAIL LOC WHERE LOC.GROUP_CODE = 'WH_LOCATION' AND LOC.CODE = tbls.LOCATION_PLACE), '') AS LOCATION_PLACE_NAME , REGISTER_USER_ID , ISNULL((SELECT tsu.USER_NAME FROM TB_SMS_USER tsu WHERE tsu.USER_ID = tbls.REGISTER_USER_ID),'') AS REGISTER_USER_NAME , REGISTER_DATE_TIME FROM TB_BMS_LOCATION_SCAN tbls WITH (NOLOCK) WHERE SCAN_DATE BETWEEN CONVERT(VARCHAR(10), ISNULL(#{srchScanDate},''), 120) AND CONVERT(VARCHAR(10), GETDATE(), 120)
AND LOCATION_STATUS = #{srchLocationStatus}
ORDER BY REGISTER_DATE_TIME DESC

mapper.update:
/* PdaLocationPaloMapper.updateOrigLocation : 반입 로케이션 초기화 */
IF(#{srchOrigLocation} IS NOT NULL and #{srchOrigLocation} <> '')
	BEGIN
		IF (#{applyAllLoactionYn} = 'Y' and #{srchInPlanNo} IS NOT NULL and #{srchInPlanNo} <> '')
			BEGIN
				UPDATE TB_BMS_IN_PLAN_PKG
					SET 
						ORIG_LOCATION_PLACE = #{srchOrigLocation}
						, UPDATE_USER_ID = #{updateUserId}
			   	 		, UPDATE_DATE_TIME = GETDATE()
				WHERE IN_PLAN_NO = #{srchInPlanNo}
					AND DELETE_YN = 'N'
			END
		ELSE
			BEGIN
				UPDATE TB_BMS_IN_PLAN_PKG
					SET 
						ORIG_LOCATION_PLACE = #{srchOrigLocation}
						, UPDATE_USER_ID = #{updateUserId}
			   	 		, UPDATE_DATE_TIME = GETDATE()
				WHERE PACKING_NO = #{srchNo}

					AND IN_PLAN_NO = #{srchInPlanNo}


					AND BL_NO = #{srchBlNo}

					AND DELETE_YN = 'N'
			END
	END

mapper.select:
/* PdaLocationPaloMapper.selectOnePkgWithBmsInByPackingNo : 박스번호에 의한 박스조회 */ SELECT TOP 1 '반입' , _in.BL_NO , _pkg.PACKING_NO , _pkg.IN_PLAN_NO , _pkg.LOCATION_PLACE , _pkg.LOCATION_STATUS , _pkg.IN_CT , _pkg.WEIGHING_WT , _in.CARGO_REFERENCE_NO , _in.IN_NO , _in.OD_JOB_NO , H.CARRYOUT_STOP_YN , ISNULL(H.HOLD_HISTORY, 'N') AS HOLD_HISTORY , CASE WHEN _in.SE_INSPECTION_CODE <> '' OR _in.INSPECTION_TYPE <> '' OR _in.INSPECTION_TYPE_A <> '' OR _in.INSPECTION_TYPE_B <> '' OR _in.XRAY_INSPECTION_CODE <> '' OR _in.PALN5EM_INSPECTION_CODE <> '' THEN 'Y' ELSE 'N' END AS INSPECTION_TYPE , SUBSTRING(_out_plan.APPROVAL_DATE, 6, 5) AS APPROVAL_DATE_MMDD , _out_plan.APPROVAL_DATE , CASE WHEN DATEDIFF(DAY, _in.CARRYIN_DATE, GETDATE()) + 1 < 1 THEN 1 ELSE DATEDIFF(DAY, _in.CARRYIN_DATE, GETDATE()) + 1 END AS STORAGE_DAYS FROM TB_BMS_IN_PLAN_PKG _pkg WITH (NOLOCK) INNER JOIN TB_BMS_IN _in WITH (NOLOCK) ON _in.IN_PLAN_NO = _pkg.IN_PLAN_NO LEFT JOIN (SELECT 'Y' AS HOLD_HISTORY , OD_JOB_NO , MAX(CARRYOUT_STOP_YN) AS CARRYOUT_STOP_YN FROM TB_ECM_OD_HOLD WITH (NOLOCK) GROUP BY OD_JOB_NO ) H ON _in.OD_JOB_NO = H.OD_JOB_NO LEFT JOIN TB_BMS_OUT_PLAN _out_plan WITH (NOLOCK) ON _out_plan.IN_NO = _in.IN_NO WHERE _pkg.DELETE_YN = 'N'
AND _pkg.PACKING_NO = #{scanPackingNo}
AND _pkg.IN_PLAN_NO = #{srchInPlanNo}
AND _in.BL_NO = #{srchBlNo}

/* PdaLocationPaloMapper.selectLocationFromPkg : 박스 로케이션조회 */
SELECT TOP 1
	LOCATION_PLACE AS LOCATION_PLACE_PKG
	, LOCATION_STATUS
	, ORIG_LOCATION_PLACE AS ORIG_LOCATION_PLACE_PKG
FROM TB_BMS_IN_PLAN_PKG _pkg WITH (NOLOCK)
INNER JOIN TB_BMS_IN_PLAN _inPlan WITH (NOLOCK)
ON _pkg.IN_PLAN_NO = _inPlan.IN_PLAN_NO
WHERE _pkg.PACKING_NO = #{packingNo}

AND _pkg.IN_PLAN_NO = #{srchInPlanNo}


AND _inPlan.BL_NO = #{srchBlNo}

/* PdaLocationPaloMapper.selectLocationFromAllPkgByScan : 박스 로케이션조회 */
SELECT TOP 1
	LOCATION_PLACE AS LOCATION_PLACE_PKG
	, LOCATION_STATUS
FROM TB_BMS_IN_PLAN_PKG _pkg WITH (NOLOCK)
INNER JOIN TB_BMS_IN_PLAN _inPlan WITH (NOLOCK)
ON _pkg.IN_PLAN_NO = _inPlan.IN_PLAN_NO
WHERE

	_pkg.IN_PLAN_NO = #{srchInPlanNo}


AND _inPlan.BL_NO = #{srchBlNo}

mapper.insert:
/* PdaLocationPaloMapper.insertLocationScanLog : 로케이션 스캔로그 저장 */
INSERT INTO TB_BMS_LOCATION_SCAN (
	  SCAN_NO
	, LOCATION_STATUS
	, LOCATION_PLACE
	, BL_NO
	, STORAGE_DAYS
	, INSPECTION_YN
	, HOLD_HISTORY
	, SCAN_RESULT
	, SCAN_DATE
	, SCAN_CT
	, APPROVAL_DATE
	, REGISTER_USER_ID
	, REGISTER_DATE_TIME
)
VALUES(
	#{packingNo}
	, #{locationStatus}
	, #{locationPlace}
	, #{blNo}
	, #{storageDays}
	, #{inspectionYn}
	, #{holdHistory}
	, #{result}
	, CONVERT(VARCHAR(10),GETDATE(),120)
	, #{scanCt}
	, #{approvalDate}
	, #{registerUserId}
	, GETDATE()
)

mapper.update:
/* PdaLocationPaloMapper.updateInLocationInfo : 반입 로케이션 초기화 */
UPDATE TB_BMS_IN
SET LOCATION_PLACE = ''
WHERE 
	IN_PLAN_NO = #{inPlanNo}
	OR ORIG_IN_PLAN_NO = #{inPlanNo}

mapper.insert:
/* PdaLocationPaloMapper.insertLocation : 로케이션 저장 */
INSERT INTO TB_SMS_CODE_DETAIL (
	ENT_CODE
	, CODE_DEFINE_ID
	, CODE
	, GROUP_CODE
	, CODE_TYPE
	, NAME_DEFAULT
	, NAME_KOR
	, NAME_ENG
	, NAME_CHI
	, NAME_JPN
	, NAME_SPA
