mapper.select:
/* PdaLocationPaloMapper.getCntPkgOutCt : 출고된 박스 조회 */
SELECT
	COUNT(*) AS CNT
FROM TB_BMS_IN_PLAN_PKG WITH (NOLOCK)
WHERE PACKING_NO = #{srchNo} AND OUT_CT > 0

AND IN_PLAN_NO = #{srchInPlanNo}


AND BL_NO = #{srchBlNo}

/* PdaLocationPaloMapper.getCntOutDateTimeFromBmsOut : 출고된 박스 조회 */
SELECT
	COUNT(*) AS CNT
FROM TB_BMS_OUT_SCAN WITH (NOLOCK)
WHERE SCAN_NO IN (
	SELECT
		PACKING_NO
	FROM TB_BMS_IN_PLAN_PKG WITH (NOLOCK)
	WHERE 1=1

		AND IN_PLAN_NO = #{srchInPlanNo}


		AND BL_NO = #{srchBlNo}

) AND SCAN_RESULT = '완료'

/* PdaLocationPaloMapper.selectPkgNoInfoNew13F : new 로케이션적치 - 박스번호조회 */ SELECT TOP 1 CASE WHEN ISNULL(I.IN_NO, 0) <> 0 THEN '반입' ELSE '반입예정' END AS dGbn , P.BL_NO , P.OD_JOB_NO , P.CARGO_REFERENCE_NO , PP.PACKING_NO , PP.OUT_CT , COALESCE(I.CT, P.EX_CT) AS CT , COALESCE(I.WT, P.EX_WT) AS WT , P.IN_PLAN_NO , PP.LOCATION_PLACE , PP.ORIG_LOCATION_PLACE , I.IN_NO AS IN_NO , H.CARRYOUT_STOP_YN , ISNULL(H.HOLD_HISTORY, 'N') AS HOLD_HISTORY , ISNULL(OP.APPROVAL_DATE, '') AS APPROVAL_DATE , CASE WHEN I.IN_NO IS NULL THEN 0 WHEN DATEDIFF(DAY, CONVERT(DATE, NULLIF(LTRIM(RTRIM(I.CARRYIN_DATE)), ''), 23), GETDATE()) + 1 < 1 THEN 1 ELSE DATEDIFF(DAY, CONVERT(DATE, NULLIF(LTRIM(RTRIM(I.CARRYIN_DATE)), ''), 23), GETDATE()) + 1 END AS STORAGE_DAYS , P.SE_INSPECTION_CODE , P.PALN5EM_INSPECTION_CODE , XR.XRAY_INSPECTION_CODE AS XRAY_INSPECTION_CODE , P.INSPECTION_TYPE , P.INSPECTION_TYPE_A , P.INSPECTION_TYPE_B , P.BIG_SIZE_YN , P.INSPECTION_CUSTOMS_YN , P.INTELLECTUAL_PROP_YN , P.CRIME_SELECTION_YN , PP.DELETE_YN
, ( SELECT ALL_INSPECTION_FINISH_YN FROM TB_BMS_IN WITH (NOLOCK) WHERE IN_PLAN_NO = #{srchInPlanNo} ) AS ALL_INSPECTION_FINISH_YN
, 'N' AS ALL_INSPECTION_FINISH_YN
FROM TB_BMS_IN_PLAN_PKG PP WITH (NOLOCK) INNER JOIN TB_BMS_IN_PLAN P WITH (NOLOCK) ON PP.IN_PLAN_NO = P.IN_PLAN_NO LEFT JOIN (SELECT MAX(CARRYOUT_STOP_YN) AS CARRYOUT_STOP_YN, OD_JOB_NO, 'Y' AS HOLD_HISTORY FROM TB_ECM_OD_HOLD WITH (NOLOCK) WHERE HOLD_RELEASE_YN = 'N' GROUP BY OD_JOB_NO) H ON P.OD_JOB_NO = H.OD_JOB_NO LEFT JOIN TB_BMS_XRAY_RESULT XR ON XR.IN_PLAN_NO = PP.IN_PLAN_NO
LEFT JOIN (SELECT TOP 1 IN_NO , IN_PLAN_NO , CARRYIN_DATE , ORIG_IN_PLAN_NO , CT , WT FROM TB_BMS_IN WITH (NOLOCK) WHERE IN_PLAN_NO = #{srchInPlanNo} OR ORIG_IN_PLAN_NO = #{srchInPlanNo} ORDER BY CAST(CARRYIN_DATE + ' ' + CARRYIN_TIME AS DATETIME) DESC ) I
LEFT JOIN (SELECT NULL AS IN_NO , NULL AS IN_PLAN_NO , NULL AS CARRYIN_DATE , NULL AS ORIG_IN_PLAN_NO , NULL AS CT , NULL AS WT ) I
ON I.IN_PLAN_NO = PP.IN_PLAN_NO OR I.ORIG_IN_PLAN_NO = PP.IN_PLAN_NO LEFT JOIN TB_BMS_OUT_PLAN OP WITH (NOLOCK) ON I.IN_NO = OP.IN_NO WHERE PP.PACKING_NO = #{srchNo}
AND PP.IN_PLAN_NO = #{srchInPlanNo}
AND P.BL_NO = #{srchBlNo}

/* PdaLocationPaloMapper.getPkgPaloByPkgNo : 박스번호에 해당하는 박스 조회 */ SELECT _pkg.BL_NO , _pkg.PACKING_NO , _pkg.IN_PLAN_NO , _pkg.LOCATION_PLACE , _pkg.ORIG_LOCATION_PLACE , _pkg.LOCATION_STATUS , COALESCE(_in.CT, inPlan.EX_CT, 0) AS CT , COALESCE(_in.WT, inPlan.EX_WT, 0) AS WT , COALESCE(_in.CARGO_REFERENCE_NO, inPlan.CARGO_REFERENCE_NO, '') AS CARGO_REFERENCE_NO , _in.IN_NO , _in.OD_JOB_NO , H.CARRYOUT_STOP_YN , ISNULL(H.HOLD_HISTORY, 'N') AS HOLD_HISTORY , CASE WHEN ( _in.SE_INSPECTION_CODE <> '' OR _in.INSPECTION_TYPE <> '' OR _in.INSPECTION_TYPE_A <> '' OR _in.INSPECTION_TYPE_B <> '' OR _in.XRAY_INSPECTION_CODE <> '' OR _in.PALN5EM_INSPECTION_CODE <> '' OR _in.BIG_SIZE_YN = 'Y' OR _in.INTELLECTUAL_PROP_YN = 'Y' OR _in.INSPECTION_CUSTOMS_YN = 'Y' ) AND ISNULL(IR.M_INSPECTION_FINISH_YN, 'Y') = 'N' THEN 'Y' ELSE 'N' END AS INSPECTION , ISNULL(OP.APPROVAL_DATE, '') AS APPROVAL_DATE , CASE WHEN DATEDIFF(DAY, latest_in.CARRYIN_DATE, GETDATE()) + 1 < 1 THEN 1 ELSE ISNULL(DATEDIFF(DAY, latest_in.CARRYIN_DATE, GETDATE()) + 1, 0) END AS STORAGE_DAYS
, (SELECT TOP 1 SCAN_RESULT FROM TB_BMS_LOCATION_SCAN scan WITH(NOLOCK) WHERE scan.SCAN_NO = _pkg.PACKING_NO ORDER BY SEQ DESC) AS SCAN_RESULT
, '' AS SCAN_RESULT
FROM TB_BMS_IN_PLAN_PKG _pkg WITH (NOLOCK) LEFT JOIN TB_BMS_IN_PLAN inPlan WITH (NOLOCK) ON _pkg.IN_PLAN_NO = inPlan.IN_PLAN_NO LEFT JOIN TB_BMS_IN _in WITH (NOLOCK) ON _in.IN_PLAN_NO = _pkg.IN_PLAN_NO LEFT JOIN (SELECT 'Y' AS HOLD_HISTORY , OD_JOB_NO , MAX(CARRYOUT_STOP_YN) AS CARRYOUT_STOP_YN FROM TB_ECM_OD_HOLD WITH (NOLOCK) GROUP BY OD_JOB_NO) H ON _in.OD_JOB_NO = H.OD_JOB_NO LEFT JOIN TB_BMS_OUT_PLAN OP WITH (NOLOCK) ON _in.IN_NO = OP.IN_NO OUTER APPLY (SELECT MIN(INSPECTION_FINISH_YN) M_INSPECTION_FINISH_YN FROM TB_BMS_INSPECT_RESULT ins WITH (NOLOCK) WHERE ins.IN_NO = _in.IN_NO GROUP BY IN_NO) IR OUTER APPLY ( SELECT TOP 1 CARRYIN_DATE FROM TB_BMS_IN i WITH (NOLOCK) WHERE i.CARGO_REFERENCE_NO = inPlan.CARGO_REFERENCE_NO ORDER BY CAST(CARRYIN_DATE + ' ' + CARRYIN_TIME AS DATETIME) DESC ) latest_in WHERE PACKING_NO = #{packingNo}
AND IN_PLAN_NO = #{inPlanNo}
AND BL_NO = #{srchBlNo}
AND DELETE_YN = 'N'

/* PdaLocationPaloMapper.selectPkgNoByPlanNoAndBlNo13F : 로케이션적치 - 박스조회 */ SELECT _pkg.BL_NO , _pkg.PACKING_NO , _pkg.IN_PLAN_NO , _pkg.OUT_CT , _pkg.LOCATION_PLACE , _pkg.ORIG_LOCATION_PLACE , _pkg.LOCATION_STATUS , COALESCE(_in.CT, inPlan.EX_CT, 0) AS CT , COALESCE(_in.WT, inPlan.EX_WT, 0) AS WT , COALESCE(_in.CARGO_REFERENCE_NO, inPlan.CARGO_REFERENCE_NO, '') AS CARGO_REFERENCE_NO , _in.IN_NO , _in.OD_JOB_NO , H.CARRYOUT_STOP_YN , ISNULL(H.HOLD_HISTORY, 'N') AS HOLD_HISTORY , CASE WHEN ( _in.SE_INSPECTION_CODE <> '' OR _in.INSPECTION_TYPE <> '' OR _in.INSPECTION_TYPE_A <> '' OR _in.INSPECTION_TYPE_B <> '' OR _in.XRAY_INSPECTION_CODE <> '' OR _in.PALN5EM_INSPECTION_CODE <> '' OR _in.BIG_SIZE_YN = 'Y' OR _in.INTELLECTUAL_PROP_YN = 'Y' OR _in.INSPECTION_CUSTOMS_YN = 'Y' ) AND ISNULL(IR.M_INSPECTION_FINISH_YN, 'Y') = 'N' THEN 'Y' ELSE 'N' END AS INSPECTION , ISNULL(OP.APPROVAL_DATE, '') AS APPROVAL_DATE , CASE WHEN DATEDIFF(DAY, latest_in.CARRYIN_DATE, GETDATE()) + 1 < 1 THEN 1 ELSE ISNULL(DATEDIFF(DAY, latest_in.CARRYIN_DATE, GETDATE()) + 1, 0) END AS STORAGE_DAYS , '' AS SCAN_RESULT FROM TB_BMS_IN_PLAN_PKG _pkg WITH (NOLOCK) LEFT JOIN TB_BMS_IN_PLAN inPlan WITH (NOLOCK) ON _pkg.IN_PLAN_NO = inPlan.IN_PLAN_NO LEFT JOIN TB_BMS_IN _in WITH (NOLOCK) ON _in.IN_PLAN_NO = _pkg.IN_PLAN_NO LEFT JOIN (SELECT 'Y' AS HOLD_HISTORY , OD_JOB_NO , MAX(CARRYOUT_STOP_YN) AS CARRYOUT_STOP_YN FROM TB_ECM_OD_HOLD WITH (NOLOCK) GROUP BY OD_JOB_NO) H ON _in.OD_JOB_NO = H.OD_JOB_NO LEFT JOIN TB_BMS_OUT_PLAN OP WITH (NOLOCK) ON _in.IN_NO = OP.IN_NO OUTER APPLY (SELECT MIN(INSPECTION_FINISH_YN) M_INSPECTION_FINISH_YN FROM TB_BMS_INSPECT_RESULT ins WITH (NOLOCK) WHERE ins.IN_NO = _in.IN_NO GROUP BY IN_NO) IR OUTER APPLY ( SELECT TOP 1 CARRYIN_DATE FROM TB_BMS_IN i WITH (NOLOCK) WHERE i.CARGO_REFERENCE_NO = inPlan.CARGO_REFERENCE_NO ORDER BY CAST(CARRYIN_DATE + ' ' + CARRYIN_TIME AS DATETIME) DESC ) latest_in WHERE 1 = 1
AND _pkg.IN_PLAN_NO = #{srchInPlanNo}
AND _pkg.BL_NO = #{srchBlNo}
AND _pkg.LOCATION_STATUS = #{srchLocationStatus}
AND _pkg.LOCATION_STATUS <> #{srchNotLocationStatus}
AND _pkg.DELETE_YN = 'N'

mapper.update:
	/* PdaLocationPaloMapper.updatePkgLocationInSeqList : 로케이션적치 - 현재 로케이션에서 변경 로케이션 으로 일괄 update */
	UPDATE TB_BMS_IN_PLAN_PKG
		SET 
			ORIG_LOCATION_PLACE = CASE 
   							WHEN ORIG_LOCATION_PLACE = '' THEN #{locationPlace}
   							ELSE ORIG_LOCATION_PLACE
   					    END
			, LOCATION_PLACE = #{locationPlace}
		   	, LOCATION_STATUS = 'L'
			, UPDATE_USER_ID = #{updateUserId}
   	 		, UPDATE_DATE_TIME = GETDATE()
	WHERE SEQ IN  (#{item.seq})
		AND DELETE_YN = 'N'

	/* PdaLocationPaloMapper.updatePkgOrigLocationInSeqList : 로케이션적치 - 현재 로케이션에서 변경 로케이션 으로 일괄 update */
	UPDATE TB_BMS_IN_PLAN_PKG
		SET 
			ORIG_LOCATION_PLACE = #{origLocationPlace}
			, UPDATE_USER_ID = #{updateUserId}
   	 		, UPDATE_DATE_TIME = GETDATE()
	WHERE SEQ IN  (#{item.seq})
		AND DELETE_YN = 'N'

/* PdaLocationPaloMapper.updatePkgLocationFromCurrentToTarget : 로케이션적치 - 현재 로케이션에서 변경 로케이션 으로 일괄 update */

				UPDATE TB_BMS_IN_PLAN_PKG
					SET 
						ORIG_LOCATION_PLACE = CASE 
			   							WHEN ORIG_LOCATION_PLACE = '' THEN #{locationPlace}
			   							ELSE ORIG_LOCATION_PLACE
			   					    END
						, LOCATION_PLACE = #{locationPlace}
					   	, LOCATION_STATUS = 'L'
						, UPDATE_USER_ID = #{updateUserId}
			   	 		, UPDATE_DATE_TIME = GETDATE()
				WHERE LOCATION_PLACE = #{srchCurrentLocation}
					AND DELETE_YN = 'N'

/* PdaLocationPaloMapper.updatePkgLocationAndOrigLocation : 로케이션적치 - 반입예정 PKG 업데이트 */
IF (#{applyAllLoactionYn} = 'Y' and #{inPlanNo} IS NOT NULL and #{inPlanNo} <> '' and #{inPlanNo} > 0)
	BEGIN
		UPDATE TB_BMS_IN_PLAN_PKG
			SET 
				ORIG_LOCATION_PLACE = #{locationPlace}
			   	, LOCATION_PLACE = #{locationPlace}
			   	, LOCATION_STATUS = 'L'
				, UPDATE_USER_ID = #{updateUserId}
	   	 		, UPDATE_DATE_TIME = GETDATE()
		WHERE PACKING_NO = #{packingNo}

			AND IN_PLAN_NO = #{inPlanNo}


			AND BL_NO = #{srchBlNo}

			AND DELETE_YN = 'N'
	END
ELSE
	BEGIN
		UPDATE TB_BMS_IN_PLAN_PKG
			SET 
				ORIG_LOCATION_PLACE = CASE 
	   							WHEN ORIG_LOCATION_PLACE = '' THEN #{locationPlace}
	   							ELSE ORIG_LOCATION_PLACE
	   					    END
				, LOCATION_PLACE = #{locationPlace}
			   	, LOCATION_STATUS = 'L'
				, UPDATE_USER_ID = #{updateUserId}
	   	 		, UPDATE_DATE_TIME = GETDATE()
		WHERE PACKING_NO = #{packingNo}

			AND IN_PLAN_NO = #{inPlanNo}


			AND BL_NO = #{srchBlNo}

			AND DELETE_YN = 'N'
	END

	/* PdaLocationPaloMapper.updateOnlyOrigLocation : 로케이션적치 - 해당하는 박스번호의 최초로케이션 변경 */
	UPDATE TB_BMS_IN_PLAN_PKG
		SET 
			ORIG_LOCATION_PLACE = #{locationPlace}
			, UPDATE_USER_ID = #{updateUserId}
   	 		, UPDATE_DATE_TIME = GETDATE()
	WHERE PACKING_NO = #{packingNo}

		AND IN_PLAN_NO = #{inPlanNo}


		AND BL_NO = #{srchBlNo}

		AND DELETE_YN = 'N'
